mapper.select:
SELECT

FROM tbl_Organization


        AND OrgName LIKE CONCAT('%', #{orgName, jdbcType=NVARCHAR}, '%')


        AND OrgLoginUserName LIKE CONCAT('%', #{orgLoginUserName, jdbcType=NVARCHAR}, '%')


        AND ServiceRegion = #{serviceRegion, jdbcType=NVARCHAR}


        AND OrgAccountStatus = #{orgAccountStatus, jdbcType=NVARCHAR}


        AND OrgID = #{orgId, jdbcType=CHAR}


ORDER BY OrgID DESC
